        "decisions": [
          {
            "topic": "Decision Gate",
            "choice": "Domain + use-case + outbound + DAL/inbound + UI; RSC read, GET Route Handler, and Server Actions; RSC owns initial render and browser HTTP cache owns interactive reads.",
